const eventCooldowns=new Map();let eventPeople=new Set(),eventFloor=null,eventUntil=0,eventEndTimer=null,eventCooldownTimer=null,activeEvent=null,eventBirthday=null,birthdayDay='',birthdayPresent=new Set();
